import{_ as o,o as i,c as r,j as t,a as n,t as s,a1 as d}from"./chunks/framework.90UQlTmt.js";const g=JSON.parse('{"title":"Recipes","description":"","frontmatter":{"title":"Recipes"},"headers":[],"relativePath":"guide/recipes/index.md","filePath":"guide/recipes/index.md","lastUpdated":1786660168000}'),h={name:"guide/recipes/index.md"},c={id:"frontmatter-title",tabindex:"-1"};function l(a,e,u,p,f,m){return i(),r("div",null,[t("h1",c,[n(s(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=d('<p>Each recipe is a shape of application, a configuration that fits it, and an honest account of what that configuration costs you. They are meant to be copied and then adjusted, not read end to end.</p><p>The rest of this guide explains how the plugin works — <a href="./../caching/">the read path</a>, <a href="./../caching/keys.html">cache keys</a>, <a href="./../invalidation/">invalidation</a>, and <a href="./../reference/config.html">every option</a>. These pages assume that and only cover the decisions.</p><h2 id="which-one-am-i" tabindex="-1">Which one am I? <a class="header-anchor" href="#which-one-am-i" aria-label="Permalink to &quot;Which one am I?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If this describes you</th><th>Read</th><th>The decision it turns on</th></tr></thead><tbody><tr><td>A public site or app. Anonymous readers, content edited in the admin panel, no per-user responses.</td><td><a href="./public-content.html">Public content API</a></td><td>A long <code>maxAge</code>, because invalidation makes it safe.</td></tr><tr><td>Logged-in users hitting the API with a JWT or an API token, and you want those responses cached too.</td><td><a href="./authenticated.html">Authenticated responses</a></td><td><code>hitpass: false</code> <strong>and</strong> <code>keys.useAuth: true</code>, together.</td></tr><tr><td>More than one Strapi process behind a load balancer, or a container that restarts often.</td><td><a href="./multi-instance.html">Several instances, one cache</a></td><td>Redis. The memory provider cannot do this.</td></tr><tr><td>Most of the API is fine, but two or three endpoints are slow enough to hurt.</td><td><a href="./expensive-routes.html">A few expensive routes</a></td><td><code>injectDefaultRoutes: false</code> and an explicit route list.</td></tr><tr><td>Many locales, or clients that send long <code>filters</code>/<code>populate</code>/<code>pagination</code> query strings.</td><td><a href="./i18n-and-query.html">Locales and query-heavy APIs</a></td><td>Whether <code>useQueryParams</code> is <code>true</code> or an allow-list.</td></tr><tr><td>A preview or draft workflow that must always show the current editorial state.</td><td><a href="./previews-drafts.html">Previews and drafts</a></td><td>A <code>hitpass</code> that recognises preview traffic.</td></tr></tbody></table><p>More than one of these usually applies at once. They compose: the multi-instance recipe is a provider choice, the query recipe is a key choice, and neither conflicts with the others.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Every duration in this plugin is <strong>milliseconds</strong>. <code>3600000</code> is one hour.</li><li>Turn on <code>enableXCacheHeaders</code> while you are configuring. Every recipe below verifies itself with it, and you can turn it off again afterwards.</li><li>Nothing is cached until you list content types in <code>strategy.contentTypes</code>. If you have not installed the plugin yet, start with <a href="./../getting-started.html">Getting started</a>.</li></ul>',7))])}const w=o(h,[["render",l]]);export{g as __pageData,w as default};
